1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import type { ModSummary } from "@/lib/mods-catalog";
5	import { ModCard } from "./ModCard";
6	import { QuickAddButton, type QuickAddServer } from "./QuickAddButton";
7	import { IconSearch } from "./icons";
8	
9	/**
10	 * The interactive core of NxLabs's browse experience — search, chip
11	 * filtering, and sort, all client-side over the mods already fetched by the
12	 * server component (the whole catalogue per family tops out at 39 rows, so
13	 * this is genuinely instant rather than a debounced round trip). This is
14	 * what makes the store feel like a real app rather than a static grid: every
15	 * control here re-derives the SAME real fields (downloads, avgRating,
16	 * createdAt, category, gameFamily) already on each `ModSummary` — nothing
17	 * decorative, nothing re-fetched.
18	 *
19	 * All props are plain serializable data, NOT functions — this is a Client
20	 * Component instantiated from a Server Component, and React can't pass a
21	 * closure across that boundary (confirmed live: "Functions cannot be passed
22	 * directly to Client Components" crashed every page using an earlier
23	 * `hrefFor`/`renderExtra` function-prop version of this component). `basePath`
24	 * + the mod's own `gameFamily`/`slug` is enough to build every href (both the
25	 * marketing and portal detail routes follow the same `/family/slug` shape).
26	 * `serversByFamily` is the portal's "Add to my server" data, keyed by family —
27	 * omitted entirely on the public marketing pages, which have no such thing.
28	 */
29	export type SortKey = "featured" | "downloads" | "latest" | "rating";
30	
31	const SORTS: { key: SortKey; label: string }[] = [
32	  { key: "featured", label: "Featured" },
33	  { key: "downloads", label: "Most Downloaded" },
34	  { key: "latest", label: "Latest" },
35	  { key: "rating", label: "Top Rated" },
36	];
37	
38	export function StoreBrowser({
39	  mods,
40	  chips,
41	  chipField,
42	  basePath,
43	  showGameBadge = false,
44	  serversByFamily,
45	  deployHref,
46	  searchPlaceholder = "Search mods, plugins, and more…",
47	  emptyLabel = "No mods match your filters yet.",
48	}: {
49	  mods: ModSummary[];
50	  chips: { key: string; label: string; count: number }[];
51	  chipField: "gameFamily" | "category";
52	  /** Detail route prefix — `${basePath}/${mod.gameFamily}/${mod.slug}`. */
53	  basePath: string;
54	  showGameBadge?: boolean;
55	  /** Portal only: this viewer's eligible servers per game family, for the QuickAddButton row. */
56	  serversByFamily?: Record<string, QuickAddServer[]>;
57	  /** Portal only: where "order one" points when there's no matching server. */
58	  deployHref?: string;
59	  searchPlaceholder?: string;
60	  emptyLabel?: string;
61	}) {
62	  const [activeChip, setActiveChip] = useState<string | null>(null);
63	  const [query, setQuery] = useState("");
64	  const [sort, setSort] = useState<SortKey>("featured");
65	
66	  const filtered = useMemo(() => {
67	    let list = mods;
68	    if (activeChip) list = list.filter((m) => m[chipField] === activeChip);
69	    const q = query.trim().toLowerCase();
70	    if (q) {
71	      list = list.filter(
72	        (m) =>
73	          m.name.toLowerCase().includes(q) ||
74	          m.category.toLowerCase().includes(q) ||
75	          (m.description ?? "").toLowerCase().includes(q)
76	      );
77	    }
78	    const sorted = [...list];
79	    if (sort === "downloads") sorted.sort((a, b) => (b.downloads ?? 0) - (a.downloads ?? 0));
80	    else if (sort === "latest") sorted.sort((a, b) => +new Date(b.createdAt) - +new Date(a.createdAt));
81	    else if (sort === "rating")
82	      sorted.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
83	    else sorted.sort((a, b) => Number(b.featured) - Number(a.featured) || (b.downloads ?? 0) - (a.downloads ?? 0));
84	    return sorted;
85	  }, [mods, activeChip, query, sort, chipField]);
86	
87	  return (
88	    <div>
89	      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
90	        <div className="relative w-full sm:max-w-xs">
91	          <IconSearch
92	            className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
93	            size={16}
94	          />
95	          <input
96	            value={query}
97	            onChange={(e) => setQuery(e.target.value)}
98	            placeholder={searchPlaceholder}
99	            aria-label="Search mods"
100	            className="input w-full pl-9 text-sm"
101	          />
102	        </div>
103	        <div className="flex flex-wrap gap-1 rounded-full border border-white/10 p-1">
104	          {SORTS.map((s) => (
105	            <button
106	              key={s.key}
107	              type="button"
108	              onClick={() => setSort(s.key)}
109	              className={`rounded-full px-3 py-1.5 text-xs font-medium transition-colors ${
110	                sort === s.key ? "bg-brand-500 text-white" : "text-[var(--fg-muted)] hover:text-[var(--fg)]"
111	              }`}
112	            >
113	              {s.label}
114	            </button>
115	          ))}
116	        </div>
117	      </div>
118	
119	      {chips.length > 0 && (
120	        <div className="mb-6 flex flex-wrap gap-2">
121	          <button
122	            type="button"
123	            onClick={() => setActiveChip(null)}
124	            className={`rounded-full border px-4 py-1.5 text-sm ${
125	              !activeChip ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
126	            }`}
127	          >
128	            All ({mods.length})
129	          </button>
130	          {chips.map((c) => (
131	            <button
132	              key={c.key}
133	              type="button"
134	              onClick={() => setActiveChip(c.key)}
135	              className={`rounded-full border px-4 py-1.5 text-sm ${
136	                activeChip === c.key ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
137	              }`}
138	            >
139	              {c.label} ({c.count})
140	            </button>
141	          ))}
142	        </div>
143	      )}
144	
145	      {filtered.length === 0 ? (
146	        <p className="py-12 text-center text-sm text-[var(--fg-muted)]">{emptyLabel}</p>
147	      ) : (
148	        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
149	          {filtered.map((mod) => {
150	            const matching = serversByFamily?.[mod.gameFamily] ?? [];
151	            return (
152	              <div key={mod.id} className="flex flex-col gap-2">
153	                <ModCard mod={mod} href={`${basePath}/${mod.gameFamily}/${mod.slug}`} showGameBadge={showGameBadge} />
154	                {serversByFamily &&
155	                  (matching.length > 0 ? (
156	                    <QuickAddButton modId={mod.id} servers={matching} />
157	                  ) : (
158	                    <p className="text-xs text-tx-mute">
159	                      No matching server yet —{" "}
160	                      <a href={deployHref ?? "/dashboard/deploy"} className="text-brand-300 underline underline-offset-2">
161	                        order one
162	                      </a>
163	                      .
164	                    </p>
165	                  ))}
166	              </div>
167	            );
168	          })}
169	        </div>
170	      )}
171	    </div>
172	  );
173	}
