1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { notFound } from "next/navigation";
4	import { Section } from "@/components/marketing/primitives";
5	import { StoreBrowser } from "@/components/mods/StoreBrowser";
6	import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
7	import { listCatalogFamilies, listCatalogMods, formatDownloads } from "@/lib/mods-catalog";
8	
9	export const dynamic = "force-dynamic";
10	
11	/**
12	 * A real per-game NxLabs landing page — item 7 of the NxLabs brief. Only
13	 * rendered for families that actually have catalogued mods (real
14	 * listCatalogFamilies() rows), never a placeholder page for a game with
15	 * nothing in it.
16	 */
17	export async function generateStaticParams(): Promise<Array<{ family: string }>> {
18	  const families = await listCatalogFamilies();
19	  return families.map((f) => ({ family: f.family }));
20	}
21	
22	export async function generateMetadata({ params }: { params: Promise<{ family: string }> }): Promise<Metadata> {
23	  const { family } = await params;
24	  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
25	  return {
26	    title: `${label} Mods & Plugins — NxLabs`,
27	    description: `Browse verified ${label} mods and plugins with real download counts, licenses, and version support — download free, or add straight to your Nxeon server.`,
28	    alternates: { canonical: `/mods/games/${family}` },
29	  };
30	}
31	
32	export default async function GameModsMarketingPage({ params }: { params: Promise<{ family: string }> }) {
33	  const { family } = await params;
34	  const families = await listCatalogFamilies();
35	  const entry = families.find((f) => f.family === family);
36	  if (!entry) notFound();
37	
38	  const mods = await listCatalogMods(family);
39	  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
40	  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;
41	  const totalDownloads = mods.reduce((sum, m) => sum + (m.downloads ?? 0), 0);
42	
43	  const categoryCounts = new Map<string, number>();
44	  for (const m of mods) categoryCounts.set(m.category, (categoryCounts.get(m.category) ?? 0) + 1);
45	  const chips = [...categoryCounts.entries()]
46	    .sort((a, b) => b[1] - a[1])
47	    .map(([category, count]) => ({ key: category, label: category, count }));
48	
49	  return (
50	    <>
51	      <section className="relative overflow-hidden">
52	        {heroSlug && (
53	          <div className="absolute inset-0 -z-10">
54	            {/* eslint-disable-next-line @next/next/no-img-element */}
55	            <img src={`/games/art/${heroSlug}_hero.jpg`} alt="" className="h-full w-full object-cover opacity-30" />
56	            <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg)] via-[var(--bg)]/70 to-transparent" />
57	          </div>
58	        )}
59	        <div className="rail py-20 sm:py-28">
60	          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
61	            <Link href="/mods" className="hover:underline">
62	              NxLabs
63	            </Link>{" "}
64	            / {label}
65	          </p>
66	          <h1 className="mt-3 text-4xl font-bold tracking-tight text-[var(--fg)] sm:text-5xl">{label} mods &amp; plugins</h1>
67	          <p className="mt-4 max-w-2xl text-lg text-[var(--fg-muted)]">
68	            {entry.count} verified add-ons for {label} — real download counts, real licenses, and a direct link to the
69	            source. Free for anyone, one click if you have a matching Nxeon server.
70	          </p>
71	          <div className="mt-6 flex flex-wrap gap-6 text-sm text-[var(--fg-muted)]">
72	            <span>
73	              <strong className="text-[var(--fg)]">{entry.count}</strong> mods &amp; plugins
74	            </span>
75	            {totalDownloads > 0 && (
76	              <span>
77	                <strong className="text-[var(--fg)]">{formatDownloads(totalDownloads)}</strong> total downloads
78	              </span>
79	            )}
80	          </div>
81	          <div className="mt-6 flex gap-3">
82	            <a href="#browse" className="btn-primary">
83	              Browse {label} mods
84	            </a>
85	            <Link href={`/${family}-server-hosting`} className="btn-secondary">
86	              See {label} hosting plans
87	            </Link>
