138	/** Real, publicly-listable families — active mods with a real upstream today. */
139	export async function listCatalogFamilies(): Promise<{ family: string; label: string; count: number }[]> {
140	  const rows = await db.gameMod.groupBy({
141	    by: ["gameFamily"],
142	    where: { active: true, upstreamOk: true },
143	    _count: true,
144	    orderBy: { gameFamily: "asc" },
145	  });
146	  return rows
147	    .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
148	    .sort((a, b) => b.count - a.count);
