151	/**
152	 * Browse listing, optionally scoped to one family. Small catalogue (~124
153	 * rows) — the whole set is returned in one shot and every filter/sort/search
154	 * control on top of it (StoreBrowser) runs client-side over this array
155	 * rather than round-tripping the server, which is what makes those controls
156	 * feel instant instead of decorative.
157	 */
158	export async function listCatalogMods(family?: string): Promise<ModSummary[]> {
159	  const rows = await db.gameMod.findMany({
160	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
161	    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
162	  });
163	  const aggs = await ratingAggs(rows.map((r) => r.id));
164	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
