167	/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
168	export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
169	  const rows = await db.gameMod.findMany({
170	    where: { active: true, upstreamOk: true },
171	    select: { gameFamily: true, slug: true },
