185	export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
186	  const rows = await db.gameMod.findMany({
187	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
188	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
189	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
190	  });
191	  const aggs = await ratingAggs(rows.map((r) => r.id));
192	  // Prefer same-category matches first, client-side sort (small result set).
193	  return rows
194	    .map((r) => toSummary(r, aggs.get(r.id)))
195	    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category))
