240	/**
241	 * Real, case-insensitive search over name/category/description for one
242	 * family (or the whole catalog when family is omitted) — backs both the
243	 * marketing and portal search bars. Small catalogue, so a plain `findMany`
244	 * with `contains` is genuinely fine; no search index needed at this scale.
245	 */
246	export async function searchCatalogMods(query: string, family?: string): Promise<ModSummary[]> {
247	  const q = query.trim();
248	  if (!q) return listCatalogMods(family);
249	  const rows = await db.gameMod.findMany({
250	    where: {
251	      active: true,
252	      upstreamOk: true,
253	      ...(family ? { gameFamily: family } : {}),
254	      OR: [
255	        { name: { contains: q, mode: "insensitive" } },
256	        { category: { contains: q, mode: "insensitive" } },
257	        { description: { contains: q, mode: "insensitive" } },
258	      ],
259	    },
260	    orderBy: [{ featured: "desc" }, { downloads: "desc" }, { name: "asc" }],
261	  });
262	  const aggs = await ratingAggs(rows.map((r) => r.id));
263	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
264	}
