266	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
267	
268	/**
269	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
270	 * light-impact mods run on any active plan for the family; moderate needs at
271	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
272	 * for the family that clears the bar, or null if none does (never guesses a
273	 * number that isn't a real, active, orderable plan).
274	 */
275	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
276	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
277	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
278	  const pick = candidates[0];
279	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
280	}
281	
282	export function formatDownloads(n: number | null): string | null {
283	  if (n == null) return null;
284	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
285	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
286	  return String(n);
287	}
288	
289	export function formatBytes(bytes: number | null): string | null {
290	  if (!bytes || bytes <= 0) return null;
291	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
292	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
293	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
294	}
295	
296	/**
297	 * The real, authoritative download for a mod detail page. Prefers the
298	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
299	 * install it) so a visitor gets the actual file, not just a landing page;
300	 * falls back to the mod's own project/resource page (still the real,
301	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
302	 * be resolved live or isn't one of the three we know how to resolve.
303	 */
304	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
305	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
306	  const id = mod.sourceId ?? "";
307	  if (!id) return fallback;
308	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
309	  try {
310	    if (mod.source === "modrinth") {
311	      const headers: Record<string, string> = { "User-Agent": UA };
312	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
313	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
314	      if (!res.ok) return fallback;
315	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
316	      const v = versions[0];
317	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
318	      return file ? { url: file.url, direct: true } : fallback;
319	    }
320	    if (mod.source === "spigotmc") {
321	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
322	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
323	    }
324	    if (mod.source === "thunderstore") {
325	      const [namespace, ...rest] = id.split("-");
326	      if (!namespace || !rest.length) return fallback;
327	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
328	        headers: { "User-Agent": UA },
329	        next: { revalidate: 3600 },
330	      });
331	      if (!res.ok) return fallback;
332	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
333	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
334	    }
335	  } catch {
336	    return fallback;
337	  }
338	  return fallback;
339	}
340	
341	export const SOURCE_LABEL: Record<string, string> = {
342	  modrinth: "Modrinth",
343	  spigotmc: "SpigotMC",
344	  hangar: "Hangar",
345	  curseforge: "CurseForge",
346	  steam_workshop: "Steam Workshop",
347	  umod: "uMod",
348	  github: "GitHub",
349	  nexus: "Nexus Mods",
350	  thunderstore: "Thunderstore",
351	  codefling: "Codefling",
352	};
