import { chromium } from "playwright";

const BASE = "http://localhost:3000";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";

const browser = await chromium.launch();

async function shot(page, path, name, opts = {}) {
  await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 30000 });
  if (opts.wait) await page.waitForTimeout(opts.wait);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: !!opts.fullPage });
}

// 1. Hero image investigation on /mods
{
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto(BASE + "/mods", { waitUntil: "networkidle", timeout: 30000 });
  await page.screenshot({ path: `${OUT}/mods-hero-firstpaint.png` });
  await page.waitForTimeout(2000);
  await page.screenshot({ path: `${OUT}/mods-hero-after2s.png` });

  const info = await page.evaluate(() => {
    const img = document.querySelector('img[src*="hero-collage"]');
    if (!img) return { found: false };
    const cs = getComputedStyle(img);
    const rect = img.getBoundingClientRect();
    // walk up parents for reveal wrapper info
    let parent = img.parentElement;
    const parents = [];
    for (let i = 0; i < 4 && parent; i++) {
      const pcs = getComputedStyle(parent);
      parents.push({
        tag: parent.tagName,
        className: parent.className,
        display: pcs.display,
        opacity: pcs.opacity,
        transform: pcs.transform,
        width: pcs.width,
        height: pcs.height,
        overflow: pcs.overflow,
      });
      parent = parent.parentElement;
    }
    return {
      found: true,
      naturalWidth: img.naturalWidth,
      naturalHeight: img.naturalHeight,
      complete: img.complete,
      rect,
      display: cs.display,
      opacity: cs.opacity,
      visibility: cs.visibility,
      transform: cs.transform,
      width: cs.width,
      height: cs.height,
      objectFit: cs.objectFit,
      parents,
    };
  });
  console.log("HERO IMG INFO (first paint - after networkidle):", JSON.stringify(info, null, 2));
  await ctx.close();
}

// mobile
{
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await ctx.newPage();
  await shot(page, "/mods", "mods-hero-mobile", { wait: 1500 });
  await ctx.close();
}

await browser.close();

